// bank.ts: البنك المحلي الموحّد لِلعبة «حلبة» (دمج bank.ts القديم + دفعات bank_batch*.py).
// البنك الحقيقي في Supabase، وهذا الملف بذرة محلية تعمل عند غياب مفاتيح Supabase.
// ملاحظة: تشغيل scripts/gen_data.py يعيد كتابة هذا الملف من الدفعات ويستبدل الدمج.

/** نوع السؤال. النص هو الأصل، والصورة أو الفيديو اختياريان ويحدّدهما هذا الحقل (تعتمد عليه lib/data.ts). */
export type BankType = 'text' | 'image' | 'video';

/** نوع الوسيط المرافق للسؤال: none = نص فقط. حقل اختياري، وغيابه يعني none. */
export type BankMediaType = 'image' | 'video' | 'none';

/** free = مرخّصة للاستخدام، own = من إنتاجنا. أي وسيط بغير ترخيص لا يُعرض أبداً. */
export type BankMediaLicense = 'free' | 'own';

export interface BankQuestion {
  id: string;
  /** slug الفئة، مطابق لـ CATALOG.slug */
  cat: string;
  points: 200 | 400 | 600;
  /** يحدّد أي حقل وسيط تقرؤه اللعبة: image ← imageUrl، video ← videoUrl */
  type: BankType;
  question: string;
  /** الإجابة الصحيحة، وهي ضمن options */
  answer: string;
  /** الإجابة الصحيحة + ٣ خيارات خاطئة */
  options: string[];
  /** مصدر النص (حديث أو آية أو كتاب)، يظهر بعد كشف الإجابة */
  source: string | null;
  /** رابط المصدر، يُحوَّل إلى QR بعد كشف الإجابة */
  sourceUrl: string | null;
  /** أيقونات تحذير: religious | film | character */
  flags: string[];

  /** رابط الصورة: مسار محلي يبدأ بـ /images/... أو /media/... أو رابط https */
  imageUrl?: string;
  /** رابط الفيديو: يوتيوب أو فيديو تفاعلي ثابت. يوتيوب يُعرض عبر youtube-nocookie بعد نقرة اللاعب */
  videoUrl?: string;
  /** نوع الوسيط. اختياري، وغيابه يعني 'none' */
  mediaType?: BankMediaType;
  /** سطر النسبة تحت الوسيط، مثل: «الصورة: اسم المصوّر، CC BY-SA 4.0، ويكيميديا كومنز» */
  mediaCredit?: string | null;
  /** إلزامي عملياً لكل سؤال بوسيط (free أو own) */
  mediaLicense?: BankMediaLicense;
}

/** نوع الوسيط الفعلي للسؤال: يقرأ mediaType إن وُجد، وإلا يستنتجه من الحقول. */
export function resolveMediaType(q: BankQuestion): BankMediaType {
  if (q.mediaType) return q.mediaType;
  if (q.imageUrl) return 'image';
  if (q.videoUrl) return 'video';
  return 'none';
}

